            Steps = ["Brown ground beef in a skillet.", "Add taco seasoning and water, simmer 5 minutes.", "Warm taco shells in the oven.", "Fill shells with beef.", "Top with lettuce, tomato, cheese, and sour cream."],
            TotalRatings = 15, RatingSum = 60
        },
        new()
        {
            Id = 4, Title = "Pasta Carbonara", Category = "Italian",
            Description = "Creamy Roman pasta made with eggs, pecorino, and guanciale.",
            Ingredients = ["Spaghetti", "Guanciale", "Egg yolks", "Pecorino Romano", "Black pepper"],
            Steps = ["Cook spaghetti in salted water until al dente.", "Crisp guanciale in a pan.", "Whisk egg yolks with grated pecorino and pepper.", "Toss hot pasta with guanciale.", "Remove from heat, stir in egg mixture quickly.", "Serve immediately with extra pecorino."],
            TotalRatings = 10, RatingSum = 45
