            Description = "Stir-fried rice noodles with shrimp, peanuts, and tangy sauce.",
            Ingredients = ["Rice noodles", "Shrimp", "Eggs", "Bean sprouts", "Peanuts", "Lime", "Fish sauce", "Tamarind paste", "Sugar", "Garlic"],
            Steps = ["Soak rice noodles in warm water for 30 minutes.", "Mix fish sauce, tamarind, and sugar for the sauce.", "Stir-fry garlic and shrimp.", "Push aside, scramble eggs in the pan.", "Add drained noodles and sauce, toss to coat.", "Serve with bean sprouts, crushed peanuts, and lime."],
