@page "/"

<PageTitle>RecipeHub — Home</PageTitle>

<div class="container py-4">
    <div class="text-center mb-5">
        <h1 class="display-4">🍳 RecipeHub</h1>
        <p class="lead text-muted">Discover and share delicious recipes from around the world</p>
    </div>

    <h2 class="mb-3">Browse by Category</h2>
    <div class="row row-cols-1 row-cols-md-3 g-4">
        @foreach (var category in Categories)
        {
            <div class="col">
                <div class="card h-100 shadow-sm">
                    <div class="card-body text-center">
                        <h4 class="card-title">@GetEmoji(category) @category</h4>
                        <p class="card-text text-muted">
                            @RecipeService.GetByCategory(category).Count recipe(s)
                        </p>
                        <a href="@($"category/{category}")" class="btn btn-outline-primary">
                            View Recipes
                        </a>
                    </div>
                </div>
            </div>
        }
    </div>

    <div class="text-center mt-5">
        <a href="submit" class="btn btn-success btn-lg">📝 Submit a Recipe</a>
    </div>
</div>

@code {
    [Inject] public RecipeService RecipeService { get; set; } = default!;

    private List<string> Categories = [];

    protected override void OnInitialized()
    {
        Categories = RecipeService.GetCategories();
    }

    private static string GetEmoji(string category) => category switch
    {
        "Italian" => "🇮🇹",
        "Indian" => "🇮🇳",
        "Mexican" => "🇲🇽",
        "Thai" => "🇹🇭",
        "Japanese" => "🇯🇵",
        "Desserts" => "🍰",
        _ => "🍽️"
    };
}

@page "/category/{CategoryName}"

<PageTitle>@CategoryName Recipes — RecipeHub</PageTitle>

<div class="container py-4">
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="">Home</a></li>
            <li class="breadcrumb-item active">@CategoryName</li>
        </ol>
    </nav>

    <h1 class="mb-4">@CategoryName Recipes</h1>

    @if (Recipes.Count == 0)
    {
        <div class="alert alert-info">No recipes found in this category.</div>
    }
    else
    {
        <div class="row row-cols-1 row-cols-md-2 g-4">
            @foreach (var recipe in Recipes)
            {
                <div class="col">
                    <div class="card h-100 shadow-sm">
                        <div class="card-body">
                            <h5 class="card-title">@recipe.Title</h5>
                            <p class="card-text">@recipe.Description</p>
                            <div class="d-flex justify-content-between align-items-center">
                                <span class="text-warning">
                                    @for (int i = 1; i <= 5; i++)
                                    {
                                        @(i <= (int)Math.Round(recipe.AverageRating) ? "★" : "☆")
                                    }
                                    <small class="text-muted ms-1">(@recipe.TotalRatings)</small>
                                </span>
                                <a href="@($"recipe/{recipe.Id}")" class="btn btn-primary btn-sm">
                                    View Recipe
                                </a>
                            </div>
                        </div>
                    </div>
                </div>
            }
        </div>
    }
</div>

@code {
    [Parameter] public string CategoryName { get; set; } = string.Empty;
    [Inject] public RecipeService RecipeService { get; set; } = default!;

    private List<RecipeHub.Models.Recipe> Recipes = [];

    protected override void OnInitialized()
    {
        Recipes = RecipeService.GetByCategory(CategoryName);
    }
}

@page "/recipe/{Id:int}"

<PageTitle>@(Recipe?.Title ?? "Recipe") — RecipeHub</PageTitle>

<div class="container py-4">
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="">Home</a></li>
            @if (Recipe is not null)
            {
                <li class="breadcrumb-item"><a href="@($"category/{Recipe.Category}")">@Recipe.Category</a></li>
                <li class="breadcrumb-item active">@Recipe.Title</li>
            }
        </ol>
    </nav>

    @if (Recipe is null)
    {
        <div class="alert alert-warning">Recipe not found.</div>
    }
    else
    {
        <h1 class="mb-2">@Recipe.Title</h1>
        <p class="lead text-muted">@Recipe.Description</p>

        <StarRating RecipeId="Recipe.Id" @rendermode="InteractiveServer" />

        <div class="row mt-4">
            <div class="col-md-5">
                <div class="card mb-4">
                    <div class="card-header"><h5 class="mb-0">🧾 Ingredients</h5></div>
                    <ul class="list-group list-group-flush">
                        @foreach (var ingredient in Recipe.Ingredients)
                        {
                            <li class="list-group-item">@ingredient</li>
                        }
                    </ul>
                </div>
            </div>
            <div class="col-md-7">
                <div class="card mb-4">
                    <div class="card-header"><h5 class="mb-0">📋 Steps</h5></div>
                    <ol class="list-group list-group-flush list-group-numbered">
                        @foreach (var step in Recipe.Steps)
                        {
                            <li class="list-group-item">@step</li>
                        }
                    </ol>
                </div>
            </div>
        </div>
    }
</div>

@code {
    [Parameter] public int Id { get; set; }
    [Inject] public RecipeService RecipeService { get; set; } = default!;

    private RecipeHub.Models.Recipe? Recipe;

    protected override void OnInitialized()
    {
        Recipe = RecipeService.GetById(Id);
    }
}

@using RecipeHub.Services

<div class="my-3">
    <span class="me-2 fs-4">
        @for (int i = 1; i <= 5; i++)
        {
            var star = i;
            <span role="button" style="cursor:pointer;"
                  @onclick="() => SubmitRating(star)"
                  class="@(star <= HoverStar ? "text-warning" : "text-secondary")"
                  @onmouseover="() => HoverStar = star"
                  @onmouseout="() => HoverStar = 0">
                ★
            </span>
        }
    </span>

    @if (Submitted)
    {
        <span class="badge bg-success">Thanks! You rated @SubmittedStars star(s).</span>
    }
    else
    {
        <span class="text-muted">
            @if (CurrentRecipe is not null)
            {
                @($"Avg: {CurrentRecipe.AverageRating:F1} ({CurrentRecipe.TotalRatings} ratings)")
            }
        </span>
    }
</div>

@code {
    [Parameter] public int RecipeId { get; set; }
    [Inject] public RecipeService RecipeService { get; set; } = default!;

    private int HoverStar;
    private bool Submitted;
    private int SubmittedStars;
    private RecipeHub.Models.Recipe? CurrentRecipe;

    protected override void OnInitialized()
    {
        CurrentRecipe = RecipeService.GetById(RecipeId);
    }

    private void SubmitRating(int stars)
    {
        RecipeService.AddRating(RecipeId, stars);
        SubmittedStars = stars;
        Submitted = true;
        CurrentRecipe = RecipeService.GetById(RecipeId);
    }
}

