@page "/submit"
@rendermode InteractiveServer

<PageTitle>Submit a Recipe — RecipeHub</PageTitle>

<div class="container py-4">
    <h1 class="mb-4">📝 Submit a Recipe</h1>

    @if (IsSubmitted)
    {
        <div class="alert alert-success">
            <h4>Recipe submitted!</h4>
            <p>Your recipe "<strong>@Model.Title</strong>" has been added to the <strong>@Model.Category</strong> category.</p>
            <a href="@($"recipe/{SubmittedId}")" class="btn btn-primary">View Your Recipe</a>
            <button class="btn btn-outline-secondary ms-2" @onclick="Reset">Submit Another</button>
        </div>
    }
    else
    {
        <EditForm Model="Model" OnValidSubmit="HandleSubmit" FormName="submitRecipe">
            <DataAnnotationsValidator />
            <ValidationSummary class="text-danger" />

            <div class="mb-3">
                <label for="title" class="form-label">Recipe Title</label>
                <InputText id="title" @bind-Value="Model.Title" class="form-control" placeholder="e.g., Classic Margherita Pizza" />
                <ValidationMessage For="() => Model.Title" class="text-danger" />
            </div>

            <div class="mb-3">
                <label for="category" class="form-label">Category</label>
                <InputSelect id="category" @bind-Value="Model.Category" class="form-select">
                    <option value="">— Select a category —</option>
                    <option value="Italian">Italian</option>
                    <option value="Indian">Indian</option>
                    <option value="Mexican">Mexican</option>
                    <option value="Thai">Thai</option>
                    <option value="Japanese">Japanese</option>
                    <option value="Desserts">Desserts</option>
                    <option value="Other">Other</option>
                </InputSelect>
                <ValidationMessage For="() => Model.Category" class="text-danger" />
            </div>

            <div class="mb-3">
                <label for="description" class="form-label">Short Description</label>
                <InputTextArea id="description" @bind-Value="Model.Description" class="form-control" rows="2" />
                <ValidationMessage For="() => Model.Description" class="text-danger" />
            </div>

            <div class="mb-3">
                <label class="form-label">Ingredients</label>
                <p class="text-muted small">One ingredient per line</p>
                <InputTextArea @bind-Value="IngredientsText" class="form-control" rows="5"
                               placeholder="Pizza dough&#10;Tomato sauce&#10;Mozzarella" />
            </div>

            <div class="mb-3">
                <label class="form-label">Steps</label>
                <p class="text-muted small">One step per line</p>
                <InputTextArea @bind-Value="StepsText" class="form-control" rows="5"
                               placeholder="Preheat oven to 400°F.&#10;Roll out the dough.&#10;Add toppings and bake." />
            </div>

            <button type="submit" class="btn btn-success">Submit Recipe</button>
            <a href="" class="btn btn-outline-secondary ms-2">Cancel</a>
        </EditForm>
    }
</div>

@code {
